<a href="{{ route('messages.show', [$conversation, ...(($riderFilter ?? null) && $riderFilter['selected'] ? ['rider' => $riderFilter['selected']] : [])]) }}" @class(['inbox-conversation', 'has-unread' => $conversation->unread_count > 0]) data-conversation-link="{{ $conversation->slug }}" data-inbox-name="{{ $conversation->displayName() }} {{ $conversation->reference }}" data-inbox-unread="{{ (int) $conversation->unread_count }}" @if($order?->is($conversation)) aria-current="true" @endif>
    <x-ui.identity-avatar :name="$conversation->displayName()" />
    <span class="inbox-conversation-copy"><span class="inbox-conversation-top"><strong>{{ $conversation->displayName() }}</strong><time datetime="{{ $conversation->latestMessage?->created_at->toIso8601String() }}">{{ $conversation->latestMessage?->created_at->timezone('Europe/Rome')->format('d/m H:i') }}</time></span><span class="inbox-preview">{{ $conversation->latestMessage?->user_id ? ((($riderFilter ?? null) ? $conversation->latestMessage->user?->name : null) ?? 'EA-Express').': ' : '' }}{{ $conversation->latestMessage?->body }}</span><span class="inbox-conversation-bottom"><small>{{ $conversation->reference }}</small>@if($riderFilter ?? null)<span @class(['inbox-rider-chip', 'is-unassigned' => ! $conversation->rider])><x-ui.icon name="bicycle" />{{ $conversation->rider?->name ?? 'Senza rider' }}</span>@endif @if($conversation->unread_count > 0)<span class="inbox-unread-count" aria-label="{{ $conversation->unread_count }} {{ (int) $conversation->unread_count === 1 ? 'nuovo messaggio' : 'nuovi messaggi' }} da leggere">{{ $conversation->unread_count }}</span>@else<small><x-ui.icon name="check2-all" /> Letta dal team</small>@endif</span></span>
</a>
